            if score > best_score:
                best_score = score
                best_site = i

    # If we are at home and carrying something, deposit
    if self_x == home_x and self_y == home_y and carrying > 0:
        return {'action': 'deposit'}

    # If cargo is full, go home
    if carrying >= capacity:
        if self_x < home_x:
            return {'action': 'move', 'dx': 1, 'dy': 0}
