            return {'action': 'move', 'dx': -1, 'dy': 0}
        if self_y < home_y:
            return {'action': 'move', 'dx': 0, 'dy': 1}
        if self_y > home_y:
            return {'action': 'move', 'dx': 0, 'dy': -1}
        return {'action': 'rest'}

